std::vector<int> vec = {10, 20, 30};

// Mutable Iterator (std::vector<T>::iterator)
auto mut_it = vec.begin();
*mut_it = 100; // OK: Modifies the element

// Const Iterator (std::vector<T>::const_iterator)
// cbegin() is preferred helper function
auto const_it = vec.cbegin();
int val = *const_it; // OK: Reads the element

// *const_it = 50; // COMPILE ERROR: Cannot modify element

// Const reference forces const_iterator use
const auto& const_ref = vec;
auto forced_cit = const_ref.begin(); // Type is const_iterator

// *forced_cit = 1; // COMPILE ERROR
